-- Per-account agent limit. Null uses control_settings.free_agent_limit, which the
-- app sets from FREE_AGENT_LIMIT. Both null means no limit. Replaces the constant
-- check in 0005 so a higher plan can raise one account without another migration.
-- Append-only: do not edit this file.
ALTER TABLE "user" ADD COLUMN agent_limit INTEGER;

CREATE TABLE IF NOT EXISTS control_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  free_agent_limit INTEGER
);

DROP TRIGGER IF EXISTS tenants_agent_limit;
CREATE TRIGGER tenants_agent_limit
BEFORE INSERT ON tenants
FOR EACH ROW
WHEN COALESCE(
  (SELECT agent_limit FROM "user" WHERE id = NEW.owner_account_id),
  (SELECT free_agent_limit FROM control_settings WHERE id = 1)
) IS NOT NULL
AND (
  SELECT COUNT(*) FROM tenants WHERE owner_account_id = NEW.owner_account_id
) >= COALESCE(
  (SELECT agent_limit FROM "user" WHERE id = NEW.owner_account_id),
  (SELECT free_agent_limit FROM control_settings WHERE id = 1)
)
BEGIN
  SELECT RAISE(ABORT, 'agent_limit');
END;
